const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pointA = ee.Geometry.Point([-50.925784, 46.694935]); // (Long, Lat)
  const pointB = ee.Geometry.Point([-58.528990, 46.809436]); // (Long, Lat)
  const date = '2019-09-19';
  const scale = 100; // Sentinel-2 bands B2, B3 are 10m, using 100m for reduceRegion

  // Function to mask clouds in Sentinel-2 L1C data
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B2', 'B3']) // Select only relevant bands
      .copyProperties(image, ['system:time_start']);
  }

  // Helper function to get image for a point and date
  async function getImageAndMilkyValue(point, name) {
    let collection = ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(point)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .map(maskS2clouds);

    let imageSize = await collection.size().getInfo();
    if (imageSize === 0) {
      // If no image on exact date, try widening the window by 2 days
      console.log(`No images found for ${name} on ${date}. Trying +/- 2 days.`);
      collection = ee.ImageCollection('COPERNICUS/S2')
        .filterBounds(point)
        .filterDate(ee.Date(date).advance(-2, 'day'), ee.Date(date).advance(3, 'day'))
        .map(maskS2clouds);
      imageSize = await collection.size().getInfo();
      if (imageSize === 0) {
        console.log(`No images for ${name} even after widening date range.`);
        return { value: null, count: 0, imageCount: 0 };
      }
    }

    // Get the median image to handle multiple images
    const image = collection.median();

    // Check for valid pixels
    const pixelCount = await image.select('B2')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: point,
        scale: scale,
        maxPixels: 1e9
      })
      .get('B2')
      .getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${name} after masking.`);
      return { value: null, count: 0, imageCount: imageSize };
    }

    // "Milky" water proxy: sum of blue (B2) and green (B3) reflectance. Higher value means more milky.
    const milkyValue = await image.addBands(image.select('B2').add(image.select('B3')).rename('milky'))
      .select('milky')
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: point,
        scale: scale,
        maxPixels: 1e9
      })
      .get('milky')
      .getInfo();

    return { value: milkyValue, count: pixelCount, imageCount: imageSize };
  }

  // Get data for Point A
  console.log("Processing Point A...");
  const dataA = await getImageAndMilkyValue(pointA, 'Point A');
  console.log(`Point A Images: ${dataA.imageCount} (Val Pixels: ${dataA.count})`);

  // Get data for Point B
  console.log("Processing Point B...");
  const dataB = await getImageAndMilkyValue(pointB, 'Point B');
  console.log(`Point B Images: ${dataB.imageCount} (Val Pixels: ${dataB.count})`);

  // 5. Validation & Final Answer
  if (dataA.imageCount === 0 || dataB.imageCount === 0) {
    console.log("C1"); // Empty Collection
    return;
  }
  if (dataA.count === 0 || dataB.count === 0) {
    console.log("C2"); // No Valid Pixels after masking
    return;
  }
  if (dataA.value === null || isNaN(dataA.value) || dataB.value === null || isNaN(dataB.value)) {
    console.log("C3"); // Calculation Failure (None, NaN)
    return;
  }

  console.log(`Point A milky value: ${dataA.value.toFixed(4)}`);
  console.log(`Point B milky value: ${dataB.value.toFixed(4)}`);

  if (dataA.value > dataB.value) {
    console.log("A"); // Point A is more milky
  } else {
    console.log("B"); // Point B is more milky or equal
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
